const { Pool } = require('pg');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key"])

  type SmartMeter @key(fields: "serialNumber") {
    serialNumber: String!
    currentKwhReading: Float!
    firmwareVersion: String!
    lastReportedAt: String!
  }
`;

const resolvers = {
  SmartMeter: {
    __resolveReference: async ({ serialNumber }, context) => {
      if (!context.customer?.accountId) {
        throw new GraphQLError('Unauthorized meter inquiry', { extensions: { code: 'UNAUTHORIZED' } });
      }
      const res = await pool.query(
        'SELECT serial_number, current_kwh, firmware_rev, updated_at FROM smart_meters WHERE serial_number = $1 AND customer_account_id = $2',
        [serialNumber, context.customer.accountId]
      );
      if (!res.rows[0]) {
        throw new GraphQLError('Meter not found or not assigned to your account', { extensions: { code: 'FORBIDDEN' } });
      }
      return {
        serialNumber: res.rows[0].serial_number,
        currentKwhReading: parseFloat(res.rows[0].current_kwh),
        firmwareVersion: res.rows[0].firmware_rev,
        lastReportedAt: res.rows[0].updated_at.toISOString(),
      };
    }
  }
};
